function parseRemark(string $remarks,string $label,string $default=''):string{if(preg_match('/(?:^|\\|)\\s*'.preg_quote($label,'/').'\\s*:\\s*([^|]+)/i',$remarks,$m))return trim($m[1]);return $default;}
function auditEdit(mysqli $c,int $businessId,int $branchId,int $userId,int $pawnId,array $old,array $new):void{if(!hasTable($c,'audit_logs'))return;$s=$c->prepare("INSERT INTO audit_logs (business_id,branch_id,user_id,module_code,action_type,reference_table,reference_id,description,old_values_json,new_values_json,ip_address,user_agent) VALUES (?,?,?,'pawn.edit','Update','pawn_entries',?,'Updated pawn entry',?,?,?,?)");if(!$s)return;$oj=json_encode($old,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$nj=json_encode($new,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$ip=(string)($_SERVER['REMOTE_ADDR']??'');$ua=(string)($_SERVER['HTTP_USER_AGENT']??'');$s->bind_param('iiiissss',$businessId,$branchId,$userId,$pawnId,$oj,$nj,$ip,$ua);$s->execute();$s->close();}
function loadPawn(mysqli $c,int $id,int $businessId):array{$sql="SELECT p.*,COALESCE(c.customer_name,'') customer_name,COALESCE(c.customer_code,'') customer_code,COALESCE(c.mobile,'') mobile,COALESCE(c.alternate_mobile,'') alternate_mobile,COALESCE(c.email,'') email,COALESCE(c.address_line1,'') address_line1,COALESCE(c.address_line2,'') address_line2,COALESCE(c.city,'') city,COALESCE(c.state,'') state,COALESCE(c.pincode,'') pincode,COALESCE(pc.category_name,'') category_name,COALESCE(pc.category_code,'') category_code,COALESCE(b.branch_name,'') branch_name FROM pawn_entries p LEFT JOIN customers c ON c.id=p.customer_id AND c.business_id=p.business_id LEFT JOIN pawn_categories pc ON pc.id=p.pawn_category_id AND pc.business_id=p.business_id LEFT JOIN branches b ON b.id=p.branch_id AND b.business_id=p.business_id WHERE p.id=? AND p.business_id=? LIMIT 1";$s=$c->prepare($sql);if(!$s)throw new RuntimeException('Unable to load pawn entry: '.$c->error);$s->bind_param('ii',$id,$businessId);$s->execute();$p=$s->get_result()->fetch_assoc();$s->close();if(!$p)throw new RuntimeException('Pawn entry not found for Pawn ID '.$id.' and Business ID '.$businessId.'.');$remarks=(string)($p['remarks']??'');foreach(['loan_type'=>['Loan Type','General'],'id_proof_type'=>['ID Proof Type',''],'id_proof_number'=>['ID Proof',''],'document_charge'=>['Document Charge','0'],'other_charge'=>['Other Charge','0'],'disbursement_payment_method_id'=>['Disbursement Method ID',''],'payment_reference'=>['Payment Reference',''],'tenure_months'=>['Tenure','0']] as $col=>$cfg){if(!array_key_exists($col,$p)){$v=parseRemark($remarks,$cfg[0],$cfg[1]);if($col==='tenure_months')$v=preg_replace('/[^0-9]/','',$v);if(in_array($col,['document_charge','other_charge'],true))$v=preg_replace('/[^0-9.\\-]/','',$v);$p[$col]=$v;}}$p['total_stone_weight']=$p['total_stone_weight']??0;$p['total_estimated_value']=$p['total_estimated_value']??0;$p['customer_address']=implode(', ',array_filter([$p['address_line1'],$p['address_l