$set=[];$types='';$params=[];foreach($values as $col=>$def){if(!hasColumn($conn,'pawn_entries',$col))continue;$set[]="`{$col}`=?";$types.=$def[0];$params[]=$def[1];}$set[]='updated_at=NOW()';$sql='UPDATE pawn_entries SET '.implode(',',$set).' WHERE id=? AND business_id=?';$types.='ii';$params[]=$id;$params[]=$businessId;$conn->begin_transaction();$s=$conn->prepare($sql);if(!$s)throw new RuntimeException('Unable to prepare pawn update: '.$conn->error);bindDynamic($s,$types,$params);if(!$s->execute())throw new RuntimeException('Unable to update pawn: '.$s->error);$s->close();$new=loadPawn($conn,$id,$businessId);auditEdit($conn,$businessId,$branchId,$userId,$id,$old,$new);$conn->commit();respond(true,'Pawn entry updated successfully.',['pawn'=>$new]);}
